"""
Implementations of TAF contracts and type checking mechanisms.
"""

from __future__ import annotations

from inspect import isfunction, signature
from textwrap import dedent, indent
from typing import Any, Optional, Protocol, TypedDict, runtime_checkable

CONTRACT_METHOD_NAME_TEMPLATE = "__taf_contract_{}__"

contracts: list[type[TafContract]] = []
contracts_by_data_type: dict[type[ContractData], type[TafContract]] = {}
data_types_by_contract: dict[Any, type[ContractData]] = {}


def get_provided_contracts(obj: Any) -> list[type[TafContract]]:
    return [contract for contract in contracts if isinstance(obj, contract)]


# TODO: annotate things properly once TypeForm[T] is implemented. This todo stretches
# across the entire library. There are lots of issues stemming from the inability to
# annotate arguments as accepting type forms.
# Read more: https://github.com/python/mypy/issues/9773


# TODO: annotate this properly once MyPy allows passing abstract SUBclasses
# into type[<abstract_base>]
# This should use AnyTafContract = TypeVar("AnyTafContract", bound=TafContract)
# and make the 'contract' type out 'obj'
def call_provider(contract: Any, obj: Any) -> ContractData:
    """Return a dictionary of data provided by the given contract.

    **Use this function to call a provider method of an object when testing it.**

    Calls the ``obj`` provider method for the given contract and returns the
    resulting data.

    :param contract: The TAF contract to call.
    :param obj: The object to call the contract method on.
    :return: The data provided by the contract.
    """
    contract_name = contract.__name__.lower()
    if not isinstance(obj, contract):
        raise TypeError(f"Contract {contract_name!r} is not implemented for {obj!r}.")
    method_name = CONTRACT_METHOD_NAME_TEMPLATE.format(contract_name)
    provider_method = getattr(obj, method_name)
    data = provider_method()
    return data


class ContractData(TypedDict):
    """Used to typehint the dictionaries returned by contract provider methods.

    All data types used by the TAF contracts MUST inherit from this class.
    """


@runtime_checkable
class TafContract(Protocol):
    """Contract base class.

    All other TAF contracts MUST inherit from this in order to be recognized as
    such.

    This class' subclass hook checks the following invariants:

    * Contract names MUST be unique - this check is case-insensitive.
    * Subclasses MUST inherit from ``typing.Protocol``.
    * Subclasses MUST define one method that conforms to the method naming
      pattern (``__taf_contract_xyz__``). The contract part of the method name
      must be lowercase.

    All contract classes must have their corresponding data type specified
    using the ``data_type`` keyword argument::

        class MyContract(Protocol, data_type=MyData):
            def __taf_contract_mycontract__(self) -> MyData: ...

    Use :class:`ContractData` to define data types for the contracts.
    """

    def __init_subclass__(cls, data_type: type[ContractData]) -> None:
        """Registers contracts and verifies contract class invariants."""
        super().__init_subclass__()

        contract_name = cls.__name__.lower()

        # XXX: MyPy doesn't like it when people use data model attributes
        # (__name__) on its precious typing special forms, hence type: ignore.
        assert Protocol in cls.__bases__, (
            f"TAF contract classes have to subclass "
            f"{Protocol.__module__}.{Protocol.__name__}"  # type: ignore
        )
        assert contract_name not in [
            (duplicate := contract).__name__.lower() for contract in contracts
        ], (
            f"{contract_name} contract is already defined in "
            f"module {duplicate.__module__!r} ({duplicate!r})."
        )
        assert hasattr(
            cls, stub_name := CONTRACT_METHOD_NAME_TEMPLATE.format(contract_name)
        ), f"missing provider method stub in {cls}: {stub_name!r}."
        assert isfunction(
            provider_method := getattr(cls, stub_name)
        ), f"{stub_name} must be a callable."

        return_annotation = signature(provider_method).return_annotation
        assert (
            # FIXME: evil eval due to 3.9 not having get_annotations
            return_annotation is data_type
            or (
                isinstance(return_annotation, str)
                and eval(return_annotation, provider_method.__globals__) is data_type
            )
        ), (
            f"{stub_name} return value annotation must be {data_type.__name__}, "
            f"not {return_annotation!r}."
        )

        if cls.__doc__ is None:
            cls.__doc__ = ""

        data_type_docs = indent(
            dedent(
                f"""
                Data type: :class:`{data_type.__name__}`

                .. autotypeddict:: {data_type.__name__}
                """
            ),
            "    ",
        )

        cls.__doc__ += data_type_docs

        contracts.append(cls)
        contracts_by_data_type[data_type] = cls
        data_types_by_contract[cls] = data_type


class SshClientConfig(ContractData):
    # TODO: This must use the Optional instead of the new-style X | Y in order for
    # autotypeddict to work - fix it.
    addr: str
    username: str
    password: Optional[str]
    private_key: Optional[str]
    port: int
    proxy: Optional[SshClientConfig]


class Ssh(TafContract, Protocol, data_type=SshClientConfig):
    """Ssh connection configuration contract.

    This contract is used to provide SSH connection configuration data to
    keywords such as ``Connect To`` from ``taf.transport.ssh``.
    """

    def __taf_contract_ssh__(self) -> SshClientConfig: ...


class PduConfig(ContractData):
    addr: str
    model: str
    model_specific_parameters: dict[str, Any]


class Pdu(TafContract, Protocol, data_type=PduConfig):
    """PDU connection configuration contract.

    This contract is used to provide PDU connection configuration data to
    keywords such as ``Setup Pdu`` from ``taf.hw.pdu``.

    The per-model parameters given via ``**kwargs`` to ``Setup Pdu`` should be
    passed via ``model_specific_parameters``. The values each PDU config class
    passes there should be based on the implementations of PDU classes from
    ``taf.hw.pdu``.
    """

    def __taf_contract_pdu__(self) -> PduConfig: ...


class RadioHeadPositionerConfig(ContractData):
    type: str
    type_specific_parameters: dict[str, Any]


class RadioHeadPositioner(TafContract, Protocol, data_type=RadioHeadPositionerConfig):
    """Radio head positioner configuration contract.

    This contract is used to provide radio head positioner configuration data to
    libraries that connect to and control radio head positioners.

    The per-type parameters are given to the libraries via parameters specified
    in their respective interfaces.
    """

    def __taf_contract_radioheadpositioner__(self) -> RadioHeadPositionerConfig: ...
